  expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "contact": " Ada@x "})).toBeNull();
  expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"})).toBeNull();
  expect(await ui.editPerson(pg_uma, p_cam, {"terms": "3", "termsFrom": "2026-03-12"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00", "from": "2026-03-25"})).toBe(true);
  await ui.setToday(pg_uma, "2026-03-27");

